// Generated by OrchestKit Claude Plugin
// Created: 2026-09-14

// Product MCP server: read-only tools for OrchestKit's CLI actions.
// Distinct from the docs MCP at /api/mcp; this surface exposes the
// non-destructive CLI actions (list skills, install plan, doctor)
// so agents can plan installs without executing them.
//
// Every tool is read-only by construction. The install_plan tool
// returns commands to run; it runs nothing. The doctor_check tool
// validates pasted config fragments against documented schemas; it
// reads only the input.
//
// Spec: https://modelcontextprotocol.io/specification (Streamable HTTP)

import { SITE } from "@/lib/constants";
import { SKILLS } from "@/lib/generated/skills-data";

export const dynamic = "force-dynamic";

const PROTOCOL_VERSION = "2025-06-18";

type ToolResult = {
	content: Array<{ type: "text"; text: string }>;
	_meta?: Record<string, unknown>;
	isError?: boolean;
};

// User-invocable skills from generated data (userInvocable: true)
function getUserInvocableSkills() {
	return Object.values(SKILLS).filter((s) => s.userInvocable);
}

// All skills for filtering in install_plan
function getAllSkillNames(): string[] {
	return Object.keys(SKILLS);
}

const TOOLS = [
	{
		name: "orchestkit_list_skills",
		description:
			"List all user-invocable OrchestKit skills with names, descriptions, and documentation URLs. Use this to discover available skills. Returns an array of skill objects.",
		inputSchema: {
			type: "object" as const,
			properties: {},
		},
		annotations: {
			readOnlyHint: true,
			destructiveHint: false,
			idempotentHint: true,
			openWorldHint: false,
		},
		run: (): ToolResult => {
			const skills = getUserInvocableSkills();
			if (skills.length === 0) {
				return {
					content: [
						{
							type: "text",
							text: "No user-invocable skills found. See all skills at https://orchestkit.yonyon.ai/docs/reference/skills",
						},
					],
				};
			}
			const lines = skills.map((s) => {
				const url = `${SITE.domain}/docs/reference/skills/${s.name}`;
				return `- **${s.name}**: ${s.description.split(".")[0]}. [Docs](${url})`;
			});
			return {
				content: [
					{
						type: "text",
						text: `# OrchestKit Skills (${skills.length})\n\n${lines.join("\n")}`,
					},
				],
			};
		},
	},
	{
		name: "orchestkit_install_plan",
		description:
			"Generate an install plan for OrchestKit. Given an optional goal or skill names, returns the exact install and invocation commands. This tool PLANS ONLY; it executes nothing.",
		inputSchema: {
			type: "object" as const,
			properties: {
				goal: {
					type: "string",
					description:
						"Optional goal description. Used to suggest relevant skills if provided.",
				},
				skills: {
					type: "array",
					items: { type: "string" },
					description:
						"Optional list of skill names to include. Valid names: " +
						getAllSkillNames().slice(0, 10).join(", ") +
						"...",
				},
			},
		},
		annotations: {
			readOnlyHint: true,
			destructiveHint: false,
			idempotentHint: true,
			openWorldHint: false,
		},
		run: (args: Record<string, unknown>): ToolResult => {
			const goal = args.goal ? String(args.goal) : undefined;
			const skillNames = Array.isArray(args.skills)
				? (args.skills as string[])
				: [];

			// Validate skill names
			const validSkills = new Set(getAllSkillNames());
			const invalid = skillNames.filter((s) => !validSkills.has(s));
			if (invalid.length > 0) {
				return {
					content: [
						{
							type: "text",
							text: `Invalid skill names: ${invalid.join(", ")}. Run orchestkit_list_skills to discover valid names.`,
						},
					],
					isError: true,
				};
			}

			// Build the plan
			const lines: string[] = ["# OrchestKit Install Plan\n"];

			// Install command
			lines.push("## Installation");
			lines.push("```bash");
			lines.push(SITE.installCommand);
			lines.push("```\n");

			// Skill invocation examples
			if (skillNames.length > 0) {
				lines.push("## Skill Invocations");
				for (const name of skillNames) {
					const skill = SKILLS[name];
					if (skill) {
						lines.push(`### ${name}`);
						lines.push("```");
						lines.push(`/ork:${name}`);
						lines.push("```\n");
					}
				}
			}

			// Goal-based suggestions
			if (goal && skillNames.length === 0) {
				lines.push("## Suggested Skills");
				lines.push(
					`Based on your goal "${goal}", explore skills at ${SITE.domain}/docs/reference/skills`,
				);
			}

			lines.push(`## Documentation`);
			lines.push(`- Skills reference: ${SITE.domain}/docs/reference/skills`);
			lines.push(`- Agents reference: ${SITE.domain}/docs/reference/agents`);
			lines.push(`- Installation guide: ${SITE.domain}/docs/getting-started/installation`);

			return {
				content: [{ type: "text", text: lines.join("\n") }],
			};
		},
	},
	{
		name: "orchestkit_doctor_check",
		description:
			"Validate a PASTED configuration fragment against OrchestKit's documented schemas. Use this to check a hooks block, plugin marketplace entry, or other config snippet BEFORE applying it. This tool READS ONLY the input; it touches no files.",
		inputSchema: {
			type: "object" as const,
			properties: {
				config: {
					type: "string",
					description:
						"The configuration fragment to validate (JSON or YAML string).",
				},
				type: {
					type: "string",
					enum: ["hooks", "plugin", "skill", "agent"],
					description: "The type of configuration to validate against.",
				},
			},
			required: ["config", "type"],
		},
		annotations: {
			readOnlyHint: true,
			destructiveHint: false,
			idempotentHint: true,
			openWorldHint: false,
		},
		run: (args: Record<string, unknown>): ToolResult => {
			const config = args.config ? String(args.config) : "";
			const type = args.type ? String(args.type) : "";

			if (!config.trim()) {
				return {
					content: [
						{
							type: "text",
							text: "Missing required parameter: config. Provide the configuration fragment to validate.",
						},
					],
					isError: true,
				};
			}

			const validTypes = ["hooks", "plugin", "skill", "agent"];
			if (!validTypes.includes(type)) {
				return {
					content: [
						{
							type: "text",
							text: `Invalid type "${type}". Valid types: ${validTypes.join(", ")}`,
						},
					],
					isError: true,
				};
			}

			// Parse the config (JSON or basic YAML-like)
			let parsed: unknown;
			try {
				if (config.trim().startsWith("{") || config.trim().startsWith("[")) {
					parsed = JSON.parse(config);
				} else {
					// Basic YAML-like validation - just check structure
					parsed = config;
				}
			} catch (e) {
				return {
					content: [
						{
							type: "text",
							text: `Parse error: ${(e as Error).message}. Provide valid JSON or YAML.`,
						},
					],
					isError: true,
				};
			}

			// Perform validation based on type
			const findings: string[] = [];

			if (type === "hooks") {
				if (typeof parsed === "object" && parsed !== null) {
					const hooks = parsed as Record<string, unknown>;
					if (!hooks["hooks"] && !hooks["pre-tool-use"] && !hooks["post-tool-use"]) {
						findings.push("No hooks block found. Expected 'hooks' key with event types.");
					}
					if (Array.isArray(hooks["hooks"])) {
						for (const h of hooks["hooks"]) {
							if (typeof h === "object" && h !== null) {
								const hook = h as Record<string, unknown>;
								if (!hook["matcher"]) {
									findings.push("Hook missing 'matcher' field.");
								}
								if (!hook["hooks"]) {
									findings.push("Hook missing 'hooks' array.");
								}
							}
						}
					}
				}
			}

			if (type === "plugin") {
				if (typeof parsed === "object" && parsed !== null) {
					const plugin = parsed as Record<string, unknown>;
					if (!plugin["name"]) {
						findings.push("Plugin missing 'name' field.");
					}
					if (!plugin["version"]) {
						findings.push("Plugin missing 'version' field.");
					}
				}
			}

			if (type === "skill") {
				if (typeof parsed === "object" && parsed !== null) {
					const skill = parsed as Record<string, unknown>;
					if (!skill["name"]) {
						findings.push("Skill missing 'name' field.");
					}
					if (!skill["description"]) {
						findings.push("Skill missing 'description' field.");
					}
				}
			}

			if (type === "agent") {
				if (typeof parsed === "object" && parsed !== null) {
					const agent = parsed as Record<string, unknown>;
					if (!agent["name"]) {
						findings.push("Agent missing 'name' field.");
					}
					if (!agent["description"]) {
						findings.push("Agent missing 'description' field.");
					}
				}
			}

			// Build result
			const resultLines: string[] = [
				`# Doctor Check: ${type}`,
				"",
				`Status: ${findings.length === 0 ? "PASS" : "ISSUES FOUND"}`,
			];

			if (findings.length === 0) {
				resultLines.push("");
				resultLines.push("No issues found in the provided configuration.");
			} else {
				resultLines.push("");
				resultLines.push("## Issues");
				for (const f of findings) {
					resultLines.push(`- ${f}`);
				}
			}

			resultLines.push("");
			resultLines.push("---");
			resultLines.push("_This tool validates only the pasted input. It reads no files._");

			return {
				content: [{ type: "text", text: resultLines.join("\n") }],
			};
		},
	},
] as const;

function text(value: string): ToolResult {
	return { content: [{ type: "text", text: value }] };
}

type RpcRequest = {
	jsonrpc: "2.0";
	id?: string | number | null;
	method: string;
	params?: Record<string, unknown>;
};

function rpcResult(id: RpcRequest["id"], result: unknown) {
	return { jsonrpc: "2.0" as const, id, result };
}

function rpcError(id: RpcRequest["id"], code: number, message: string) {
	return { jsonrpc: "2.0" as const, id, error: { code, message } };
}

const WRITE_METHODS = new Set([
	"resources/write",
	"prompts/write",
	"logging/setLevel",
]);

async function dispatch(req: RpcRequest): Promise<object | null> {
	// Reject write-like methods - this server is read-only
	if (WRITE_METHODS.has(req.method)) {
		return rpcError(
			req.id,
			-32600,
			`Method not allowed: ${req.method} - this server is read-only`,
		);
	}

	switch (req.method) {
		case "initialize":
			return rpcResult(req.id, {
				protocolVersion:
					(req.params?.protocolVersion as string) ?? PROTOCOL_VERSION,
				capabilities: {
					tools: { listChanged: false },
				},
				serverInfo: {
					name: `${SITE.name} Actions MCP`,
					version: SITE.version,
				},
				instructions:
					"Plan OrchestKit installations without executing. Use orchestkit_list_skills to discover skills, orchestkit_install_plan to generate commands, and orchestkit_doctor_check to validate config fragments. All tools are read-only.",
			});
		case "ping":
			return rpcResult(req.id, {});
		case "tools/list":
			return rpcResult(req.id, {
				tools: TOOLS.map((t) => ({
					name: t.name,
					description: t.description,
					inputSchema: t.inputSchema,
					annotations: t.annotations,
				})),
			});
		case "tools/call": {
			const name = req.params?.name as string;
			const args = (req.params?.arguments as Record<string, unknown>) ?? {};
			const tool = TOOLS.find((t) => t.name === name);
			if (!tool) return rpcError(req.id, -32602, `Unknown tool: ${name}`);
			return rpcResult(req.id, tool.run(args));
		}
		default:
			// Notifications carry no id — no reply.
			if (req.id === undefined || req.id === null) return null;
			return rpcError(req.id, -32601, `Method not found: ${req.method}`);
	}
}

export async function POST(request: Request) {
	let payload: unknown;
	try {
		payload = await request.json();
	} catch {
		return Response.json(rpcError(null, -32700, "Parse error"), { status: 400 });
	}

	const batch = Array.isArray(payload);
	const requests = (batch ? payload : [payload]) as RpcRequest[];
	const responses = await Promise.all(
		requests.map(async (r) => ({ request: r, response: await dispatch(r) })),
	);
	const nonNull = responses
		.map((p) => p.response)
		.filter((r): r is object => r !== null);

	// Notifications only → 202 Accepted
	if (nonNull.length === 0) return new Response(null, { status: 202 });

	return Response.json(batch ? nonNull : nonNull[0]);
}

// This stateless server initiates no server→client messages, so no SSE on GET.
export function GET() {
	return new Response("Method Not Allowed", {
		status: 405,
		headers: { Allow: "POST" },
	});
}

// CORS preflight (global CORS headers in next.config.mjs)
export function OPTIONS() {
	return new Response(null, { status: 204 });
}
